146 #[expect(clippy::too_many_arguments, reason = "init's explicit streams plus the note queue")]
147 fn run_queued<'a, R: CommandRunner>(
148     args: InitArgs,
149     global: &GlobalArgs,
150     interactive: bool,
151     prompter: &mut dyn Prompter,
152     out: &'a mut dyn Write,
153     err: &'a mut dyn Write,
154     runner: &R,
155     notes: &mut Notes,
156 ) -> Result<ExitCode, CliError> {
157     validate_flags(&args)?;
158     // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
159     let (root, no_root) = match workspace_root(global, runner) {
160         Ok(root) => (root, None),
161         Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
162             toplevel.clone(),
163             Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
164         ),
165         Err(error) => return Err(error),
166     };
167     let locator = IgnoreWalkLocator::new(&root);
168     if args.workflow && scaffold::is_initialized(&root)? {
169         // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
170         // The forge and product flags already require an artifact target.
171         if args.versioning.is_some() || !args.artifact_targets.is_empty() {
172             return Err(GraphError::InitAlreadyInitialized {
173                 path: root.join("callisto.toml"),
174             }
175             .into());
176         }
177         return run_workflow_only(&root, &locator, global, out, err, runner);
178     }
179     let facts = scaffold::detect(&root, &locator, runner)?;
180     if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
181         return Err(error.into());
182     }
183     let json = global.format == OutputFormat::Json;
184     // JSON keeps stdout for the report.
185     macro_rules! human {
186         () => {
187             if json {
188                 &mut *err
189             } else {
190                 &mut *out
191             }
192         };
193     }
194     write_facts(&facts, human!())?;
195 
196     if facts.origin.is_none() {
197         if args.workflow {
198             return Err(CliError::InitFlagRequiresOrigin {
199                 flag: "workflow",
200                 not_hosted: facts.origin_not_hosted,
201             });
202         }
203         if !args.artifact_targets.is_empty() {
204             return Err(CliError::InitFlagRequiresOrigin {
205                 flag: "artifact-target",
206                 not_hosted: facts.origin_not_hosted,
207             });
208         }
209     }
210     if !interactive && !args.yes {
211         let mut missing = vec!["--yes"];
212         missing.extend(missing_flags(&args, &facts));
213         return Err(CliError::InitRequiresYes { missing });
214     }
215     if args.yes {
216         let missing = missing_flags(&args, &facts);
217         if !missing.is_empty() {
218             return Err(CliError::InitMissingFlags { missing });
219         }
220     }
221     let prompting = interactive && !args.yes;
222     let migration = changesets::migrate(&facts.root, &facts);
223     // A dry run writes nothing, so it previews with the warning instead.
224     if !migration.public_scoped.is_empty() && !args.yes && !global.dry_run {
225         return Err(CliError::InitChangesetsAccess {
226             packages: migration.public_scoped,
227         });
228     }
229     let mut answers = collect_answers(&args, &facts, prompting, prompter)?;
230 
231     notes.items.extend(migration.diagnostics.iter().cloned());
232     notes.items.extend(migration.apply_fixed_groups(&mut answers));
233     if facts.origin.is_none() {
234         notes.items.push(callisto_model::Diagnostic {
235             code: callisto_model::DiagnosticCode::InitOriginMissing,
236             severity: callisto_model::DiagnosticSeverity::Warning,
237             message: match facts.origin_not_hosted {
238                 Some(reason) => origin_not_hosted_note(reason),
239                 None => ORIGIN_MISSING_NOTE.to_owned(),
240             },
241             package: None,
242             path: None,
243             escalated_by: None,
244             governed_by: None,
245         });
246     }
247     let shape = match scaffold::workflow_shape(&facts, answers.binaries.is_some()) {
248         Err(reason) if args.workflow => {
249             return Err(GraphError::InitWorkflowUnsupported {
250                 reason: reason.to_string(),
251             }
252             .into());
253         }
254         Err(reason) => {
255             let note = workflow_unsupported_note(reason);
256             notes.items.push(callisto_model::Diagnostic {
257                 code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
258                 severity: callisto_model::DiagnosticSeverity::Warning,
259                 message: note,
260                 package: None,
261                 path: None,
262                 escalated_by: None,
263                 governed_by: None,
264             });
265             None
266         }
267         Ok(shape) => Some(shape),
268     };
269     let want_workflow = match shape {
270         None => false,
271         Some(_) if args.workflow => true,
272         Some(_) if args.no_workflow => false,
273         Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
274         // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
275         Some(_) => facts.origin_repository.is_some(),
276     };
277     // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
278     let asked_for_workflow = args.workflow || prompting;
279     let workflow = match shape.filter(|_| want_workflow) {
280         Some(shape) => match build_workflow(&facts, shape, migration.base_branch.as_ref(), runner, human!()) {
281             Ok(built) => Some(built),
282             Err(error) if !asked_for_workflow => {
283                 let note =
284                     format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
285                 notes.items.push(callisto_model::Diagnostic {
286                     code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
287                     severity: callisto_model::DiagnosticSeverity::Warning,
288                     message: note,
289                     package: None,
290                     path: None,
291                     escalated_by: None,
292                     governed_by: None,
293                 });
294                 None
295             }
296             Err(error) => return Err(error),
297         },
298         None => None,
299     };
300     if workflow.is_none() {
301         notes.items.extend(migration.base_branch_unused());
302     }
303 
304     let config = scaffold::render_config(&facts, &answers);
305     let plan = if facts.has_commit {
306         Some(scaffold::preview(&facts, &config, &locator, runner)?)
307     } else {
308         None
309     };
310     if config
311         .lines()
312         .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
313     {
314         writeln!(human!(), "\ncallisto.toml: no settings needed, the defaults apply.")?;
315     } else {
316         writeln!(human!(), "\ncallisto.toml:\n{config}")?;
317     }
318     match plan {
319         Some((plan, pending)) => {
320             writeln!(human!(), "First release preview (`callisto release --dry-run`):")?;
321             super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human!())?;
322             // `origin` already has its own note above, so an unbound tag adds nothing.
323             if let Some(plan) = &plan {
324                 notes.items.extend(plan.diagnostics.clone());
325             }
326             notes.items.extend(super::release::pending_version_diagnostic(&pending));
327         }
328         None => writeln!(human!(), "{NO_COMMITS}")?,
329     }
330     if let Some((_, branch)) = &workflow {
331         writeln!(human!(), "\n{}", workflow_summary(&facts.root, branch))?;
332     }
333 
334     // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
335     let files = scaffold::init_files(&facts.root, workflow.is_some())?;
336     let mut report = if global.dry_run {
337         InitReport {
338             schema_version: SCHEMA_VERSION,
339             initialized: false,
340             config_path: facts.root.join("callisto.toml"),
341             config,
342             files,
343             diagnostics: Vec::new(),
344         }
345     } else {
346         // Said before the write question so a decline keeps them; `finish` skips them.
347         notes.emit(&mut *err)?;
348         if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
349             if json {
350                 let declined = InitReport {
351                     schema_version: SCHEMA_VERSION,
352                     initialized: false,
353                     config_path: facts.root.join("callisto.toml"),
354                     config,
355                     files: Vec::new(),
356                     diagnostics: std::mem::take(&mut notes.items),
357                 };
358                 return finish(&declined, std::mem::take(&mut notes.shown), global, out, err);
359             }
360             writeln!(human!(), "Initialization cancelled; nothing was written.")?;
361             return Ok(ExitCode::SUCCESS);
362         }
363         let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
364         let mut report = scaffold::write(&facts.root, &config, &permit)?;
365         if let Some((workflow, branch)) = &workflow {
366             scaffold::write_workflow(&facts.root, workflow, &permit)?;
367             notes.items.push(announce_workflow(human!(), &facts, branch)?);
368         }
369         report.files = files;
370         report
371     };
372     report.diagnostics.extend(std::mem::take(&mut notes.items));
373     finish(&report, std::mem::take(&mut notes.shown), global, out, err)
374 }
