 62 /// Asks the operator questions; a scripted implementation drives tests.
 63 pub trait Prompter {
 64     fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
 65     fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
 66     fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
 67 }
