 69 struct TerminalPrompter;
 70 
 71 impl Prompter for TerminalPrompter {
 72     fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
 73         Ok(Select::new().with_prompt(prompt).items(items).default(0).interact()?)
 74     }
 75 
 76     fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
 77         Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
 78     }
 79 
 80     fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
 81         let mut input = Input::<String>::new().with_prompt(prompt);
 82         if let Some(default) = default {
 83             input = input.default(default.to_owned());
 84         }
 85         Ok(input.interact_text()?)
 86     }
 87 }
