324                 notes.items.extend(plan.diagnostics.clone());
325             }
326             notes.items.extend(super::release::pending_version_diagnostic(&pending));
327         }
328         None => writeln!(human!(), "{NO_COMMITS}")?,
329     }
330     if let Some((_, branch)) = &workflow {
331         writeln!(human!(), "\n{}", workflow_summary(&facts.root, branch))?;
332     }
333 
334     // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
335     let files = scaffold::init_files(&facts.root, workflow.is_some())?;
336     let mut report = if global.dry_run {
337         InitReport {
338             schema_version: SCHEMA_VERSION,
339             initialized: false,
340             config_path: facts.root.join("callisto.toml"),
341             config,
342             files,
343             diagnostics: Vec::new(),
344         }
345     } else {
346         // Said before the write question so a decline keeps them; `finish` skips them.
347         notes.emit(&mut *err)?;
348         if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
349             if json {
350                 let declined = InitReport {
351                     schema_version: SCHEMA_VERSION,
352                     initialized: false,
353                     config_path: facts.root.join("callisto.toml"),
354                     config,
355                     files: Vec::new(),
356                     diagnostics: std::mem::take(&mut notes.items),
357                 };
358                 return finish(&declined, std::mem::take(&mut notes.shown), global, out, err);
359             }
360             writeln!(human!(), "Initialization cancelled; nothing was written.")?;
361             return Ok(ExitCode::SUCCESS);
362         }
363         let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
364         let mut report = scaffold::write(&facts.root, &config, &permit)?;
365         if let Some((workflow, branch)) = &workflow {
366             scaffold::write_workflow(&facts.root, workflow, &permit)?;
367             notes.items.push(announce_workflow(human!(), &facts, branch)?);
368         }
369         report.files = files;
370         report
371     };
372     report.diagnostics.extend(std::mem::take(&mut notes.items));
373     finish(&report, std::mem::take(&mut notes.shown), global, out, err)
374 }
