376 /// The one emitter for `init`'s notes and advice: stderr once in every format, and the JSON report carries them too.
377 fn finish(
378     report: &InitReport,
379     shown: usize,
380     global: &GlobalArgs,
381     out: &mut dyn Write,
382     err: &mut dyn Write,
383 ) -> Result<ExitCode, CliError> {
384     render::render_diagnostics(&report.diagnostics[shown..], None, &mut &mut *err)?;
385     if global.format == OutputFormat::Json {
386         emit_report(&mut &mut *out, report, global.dry_run)?;
387     } else {
388         render::render_init(report, &mut &mut *out)?;
389     }
390     Ok(ExitCode::SUCCESS)
391 }
